private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null || node.getLeft() == null) {
        return node;
    }
    TreeNode<T> leftChild = node.getLeft();
    TreeNode<T> leftRight = leftChild.getRight();

    // Perform rotation
    leftChild.setRight(node);
    leftChild.setParent(node.getParent());
    node.setParent(leftChild);

    node.setLeft(leftRight);
    if (leftRight != null) {
        leftRight.setParent(node);
    }

    // Update parent's child reference
    if (leftChild.getParent() != null) {
        if (leftChild.getParent().getLeft() == node) {
            leftChild.getParent().setLeft(leftChild);
        } else if (leftChild.getParent().getRight() == node) {
            leftChild.getParent().setRight(leftChild);
        }
    }

    return leftChild;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null) {
        return null;
    }
    TreeNode<T> leftChild = node.left;
    if (leftChild == null) {
        return node;
    }
    TreeNode<T> rightOfLeft = leftChild.right;

    // Perform rotation
    node.left = rightOfLeft;
    if (rightOfLeft != null) {
        rightOfLeft.parent = node;
    }

    leftChild.right = node;
    leftChild.parent = node.parent;
    node.parent = leftChild;

    return leftChild;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null) {
        return null;
    }
    TreeNode<T> left = node.getLeft();           // assume getter for left child
    if (left == null) {
        return node; // nothing to rotate
    }

    // Perform rotation
    node.setLeft(left.getRight());                 // node's new left child
    if (left.getRight() != null) {
        left.getRight().setParent(node);           // update parent of moved subtree
    }

    left.setRight(node);                           // left becomes parent of node
    TreeNode<T> parent = node.getParent();         // original parent of node
    node.setParent(left);                          // node becomes child of left
    left.setParent(parent);                        // left takes node's old parent

    // Reconnect left child to parent if parent exists
    if (parent != null) {
        if (parent.getLeft() == node) {
            parent.setLeft(left);
        } else if (parent.getRight() == node) {
            parent.setRight(left);
        }
    }

    // Return the new root of this subtree
    return left;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null || node.left == null) {
        return node;
    }
    TreeNode<T> left = node.left;
    TreeNode<T> leftRight = left.right;

    // Detach leftRight from its new parent (if present)
    if (leftRight != null) {
        leftRight.parent = node;
    }

    // Update node's parent to point to left instead of node
    if (node.parent != null) {
        if (node == node.parent.right) {
            node.parent.right = left;
        } else {
            node.parent.left = left;
        }
    }
    left.parent = node.parent;

    // Perform the rotation
    left.right = node;
    node.parent = left;
    node.left = leftRight;

    // Return the new parent of the rotated subtree
    return left;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) {
        throw new IllegalArgumentException("rotateRight called with null node");
    }
    TreeNode<T> left = node.getLeft();
    if (left == null) {
        throw new IllegalArgumentException("rotateRight called on node without left child");
    }
    // Perform the rotation
    node.setLeft(left.getRight());
    if (left.getRight() != null) {
        left.getRight().setParent(node);
    }
    left.setRight(node);
    left.setParent(node.getParent());
    TreeNode<T> parent = node.getParent();
    node.setParent(left);
    if (parent != null) {
        if (parent.getLeft() == node) {
            parent.setLeft(left);
        } else if (parent.getRight() == node) {
            parent.setRight(left);
        }
    }
    return left;
}

