public String format(LoggingEvent event) {
    if (event == null) {
        return "";
    }
    try {
        // Try to use the likely preferred method for formatted output
        return event.getFormattedMessage();
    } catch (Exception e) {
        // Fallback to the generic message if the formatted version is unavailable
        try {
            return event.getMessage();
        } catch (Exception ex) {
            // In the unlikely event that both calls fail, return an empty string
            return "";
        }
    }
}

public String format(LoggingEvent event){
    if(event == null){
        return "";
    }
    try{
        // If the event has its own formatted message (Log4j 2.x)
        try{
            return event.getFormattedMessage();
        }catch(NoSuchMethodError e){
            // Fallback to legacy Log4j 1.x API
            if(event.getMessage() != null){
                return event.getMessage().toString();
            }
        }
        // If all else fails, use the default toString representation
        return event.toString();
    }catch(Exception e){
        // Defensive: return a safe empty string on any exception
        return "";
    }
}

public String format(LoggingEvent event) {
    if (event == null) {
        return "";
    }
    try {
        // In Log4j 2, LoggingEvent has a direct method to get a formatted message
        return event.getFormattedMessage();
    } catch (Exception e) {
        // Fallback for older Log4j versions or missing method
        try {
            if (event.getMessage() != null) {
                return event.getMessage().toString();
            }
        } catch (Exception ignored) {}
        return "";
    }
}

public String format(LoggingEvent event){
    if (event == null){
        return "";
    }
    try{
        java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
        String time = sdf.format(new java.util.Date(event.getTimeStamp()));
        String level = event.getLevel() != null ? event.getLevel().toString() : "UNKNOWN";
        String logger = event.getLoggerName() != null ? event.getLoggerName() : "UnknownLogger";
        String thread = event.getThreadName() != null ? event.getThreadName() : "UnknownThread";
        String message = event.getMessage() != null ? event.getMessage() : "";
        return String.format("%s [%s] (%s:%s) - %s", time, level, logger, thread, message);
    }catch(Exception e){
        return "";
    }
}

