private int parseEndOfLine(String headerPart,int end){
    if (headerPart == null) {
        throw new IllegalArgumentException("headerPart cannot be null");
    }
    if (end < 0 || end >= headerPart.length()) {
        throw new IllegalArgumentException("end index out of bounds: " + end);
    }
    int lineEnd = headerPart.indexOf("\r\n", end);
    if (lineEnd == -1) {
        throw new IllegalStateException("End of line marker '\\r\\n' not found in headerPart");
    }
    return lineEnd;
}

private int parseEndOfLine(String headerPart, int end) {
    if (headerPart == null || end < 0 || end >= headerPart.length()) {
        return -1;
    }
    int len = headerPart.length();
    for (int i = end; i < len - 1; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
    }
    return -1;
}

private int parseEndOfLine(String headerPart,int end){
    if (headerPart == null || headerPart.length() <= 1) {
        return -1;
    }
    int maxIndex = headerPart.length() - 1;
    int start = end + 1;
    if (start > maxIndex) {
        return -1;
    }
    for (int i = start; i < maxIndex; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
    }
    return -1;
}

private int parseEndOfLine(String headerPart, int end) {
    if (headerPart == null) {
        throw new IllegalArgumentException("headerPart cannot be null");
    }
    if (end < 0 || end > headerPart.length()) {
        throw new IllegalArgumentException("end index out of bounds");
    }
    return headerPart.indexOf("\r\n", end);
}

