public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
    if (graph == null) {
        throw new IllegalArgumentException("graph must not be null");
    }
    // Identity mapping: each vertex and edge maps to itself
    return new IsomorphicGraphMapping<>(graph, graph, v -> v, e -> e);
}

public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
    if (graph == null) {
        throw new IllegalArgumentException("graph cannot be null");
    }
    Map<V, V> vertexMap = new java.util.HashMap<>();
    for (V v : graph.getVertices()) {
        vertexMap.put(v, v);
    }
    return new IsomorphicGraphMapping<>(graph, vertexMap);
}

public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
    if (graph == null) {
        throw new IllegalArgumentException("graph must not be null");
    }
    return new IsomorphicGraphMapping<V,E>() {
        @Override
        public boolean mapsVertexTo(V v1, V v2) {
            return v1 == v2 || java.util.Objects.equals(v1, v2);
        }

        @Override
        public boolean mapsEdgeTo(E e1, E e2) {
            return e1 == e2 || java.util.Objects.equals(e1, e2);
        }
    };
}

public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
    try{
        java.util.Map<V,V> mapping = new java.util.HashMap<>();
        for(V v : graph.vertexSet()){
            mapping.put(v, v);
        }
        return new IsomorphicGraphMapping<>(mapping);
    }catch(Throwable t){
        throw new RuntimeException("Failed to create identity mapping", t);
    }
}

