}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    if (!file.exists()) {
        return;
    }
    if (file.isDirectory()) {
        File[] children = file.listFiles();
        if (children != null) {
            for (File child : children) {
                forceDeleteOnExit(child);
            }
        }
    }
    file.deleteOnExit();
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file");
    }
    try {
        Runtime.getRuntime().addShutdownHook(new Thread(() -> deleteRecursive(file)));
    } catch (SecurityException e) {
        throw new IOException("Could not register shutdown hook", e);
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    java.util.Deque<File> stack = new java.util.ArrayDeque<>();
    stack.push(file);
    while (!stack.isEmpty()) {
        File current = stack.pop();
        if (current.isDirectory()) {
            File[] children = current.listFiles();
            if (children != null) {
                for (File child : children) {
                    stack.push(child);
                }
            }
        }
        current.deleteOnExit();
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    if (!file.exists()) {
        return;
    }
    Runtime.getRuntime().addShutdownHook(new Thread(() -> {
        java.util.function.Consumer<File> delete = null;
        delete = f -> {
            if (f.isDirectory()) {
                File[] children = f.listFiles();
                if (children != null) {
                    for (File child : children) {
                        delete.accept(child);
                    }
                }
            }
            if (!f.delete()) {
                throw new RuntimeException(new IOException("Failed to delete: " + f));
            }
        };
        try {
            delete.accept(file);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }));
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    if (!file.exists()) {
        return; // nothing to schedule
    }
    if (file.isDirectory()) {
        File[] children = file.listFiles();
        if (children != null) {
            for (File child : children) {
                // recursively schedule deletions for all sub-files
                forceDeleteOnExit(child);
            }
        }
    }
    try {
        // Schedule the (sub)file for deletion on JVM exit
        // deleteOnExit has no return value but may throw SecurityException
        file.deleteOnExit();
    } catch (SecurityException e) {
        throw new IOException("Unable to register file for deletion on exit: " 
                                + file.getAbsolutePath(), e);
    }
}

