@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    if (target == null || resultMap == null) {
        return;
    }
    // Collect non-null vertices
    List<V> vertices = new ArrayList<>();
    for (V v : resultMap.values()) {
        if (v != null) {
            vertices.add(v);
        }
    }
    int size = vertices.size();
    if (size < 2) {
        return; // not enough vertices for a bipartite graph
    }
    // Split vertices into two partitions: first half and second half
    int mid = size / 2;
    List<V> partA = vertices.subList(0, mid);
    List<V> partB = vertices.subList(mid, size);
    // Add edges to form a complete bipartite graph
    for (V u : partA) {
        for (V v : partB) {
            if (!target.containsEdge(u, v) && !target.containsEdge(v, u)) {
                target.addEdge(u, v);
            }
        }
    }
}

