protected int findByte(byte value, int pos) {
    // If the buffer is not initialized, we cannot search
    if (buffer == null) {
        return -1;
    }

    // Validate the starting position
    if (pos < 0 || pos >= buffer.length) {
        return -1;
    }

    // Scan forward until we find the byte or reach the end of the buffer
    for (int i = pos; i < buffer.length; i++) {
        if (buffer[i] == value) {
            return i;
        }
    }

    // Byte not found
    return -1;
}

