public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    if (out == null) throw new NullPointerException("OutputStream cannot be null");
    if (message == null) throw new NullPointerException("Message cannot be null");
    if (schema == null) throw new NullPointerException("Schema cannot be null");
    if (buffer == null) throw new NullPointerException("Buffer cannot be null");

    // Reset the buffer and serialize the message into it
    buffer.reset(); // assume LinkedBuffer has reset() to clear its state
    schema.writeTo(buffer, message);
    int size = buffer.getPosition(); // number of bytes written

    // Write the length prefix as a Varint32
    int temp = size;
    while ((temp & ~0x7F) != 0) {
        out.write((temp & 0x7F) | 0x80);
        temp >>>= 7;
    }
    out.write(temp & 0x7F);

    // Write the serialized message bytes
    byte[] data = buffer.getItemBuffer(); // assume this returns the underlying byte array
    out.write(data, 0, size);

    // Clear buffer for next use
    buffer.clear(); // assume LinkedBuffer has a clear() method

    return size;
}

public static <T> int function ( OutputStream arg0, T arg1, Schema<T> arg2, LinkedBuffer arg3 ) throws IOException {
    int size = arg2.getSerializedSize(arg1, arg3);
    CodedOutputStream cos = CodedOutputStream.newInstance(arg0);
    cos.writeRawVarint32(size);
    arg2.writeTo(cos, arg1, arg3);
    cos.flush();
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream must not be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema must not be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message must not be null");
    }
    try {
        // Ensure buffer is available; if null, create a default one
        if (buffer == null) {
            buffer = LinkedBuffer.allocate(512);
        } else {
            buffer.reset();
        }

        // Write the message to the buffer
        // Assume Schema has a write method that accepts a LinkedBuffer
        schema.write(message, buffer);

        // Determine the payload size
        int payloadSize = buffer.position();

        // Write 4‑byte big‑endian length prefix
        out.write(new byte[]{
            (byte) (payloadSize >>> 24),
            (byte) (payloadSize >>> 16),
            (byte) (payloadSize >>> 8),
            (byte) payloadSize
        });

        // Write the serialized payload
        out.write(buffer.array(), 0, payloadSize);

        return payloadSize;
    } catch (Exception e) {
        throw new IOException("Unable to write delimited message", e);
    }
}

