public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new NullPointerException("out");
    }
    if (message == null) {
        throw new NullPointerException("message");
    }
    if (schema == null) {
        throw new NullPointerException("schema");
    }
    if (buffer == null) {
        throw new NullPointerException("buffer");
    }

    int size = schema.getSerializedSize(message);
    // Write the length prefix (as a varint) followed by the message data
    CodedOutputStream cos = CodedOutputStream.newInstance(buffer);
    cos.writeInt32NoTag(size);          // length field
    schema.writeTo(message, cos, buffer);
    cos.flush();

    byte[] data = buffer.get();
    out.write(data, 0, buffer.size());
    buffer.clear();

    return size;
}

