        if (!(genericType instanceof ParameterizedType)) {
            return null; // not parameterized
        }
        ParameterizedType targetParamType = (ParameterizedType) genericType;
        Type rawType = targetParamType.getRawType();
        if (!(rawType instanceof Class)) {
            return null;
        }
        Class<?> rawClass = (Class<?>) rawType;

        // Build mapping of type variables to actual types by walking targetType hierarchy
        Map<TypeVariable<?>, Type> typeVarAssigns = new HashMap<>();
        buildTypeVarAssigns(targetType, typeVarAssigns);

        // Resolve each type argument
        Type[] args = targetParamType.getActualTypeArguments();
        Class<?>[] result = new Class<?>[args.length];
        for (int i = 0; i < args.length; i++) {
            Class<?> resolved = toClass(args[i], typeVarAssigns);
            if (resolved == null) {
                return null; // cannot resolve
            }
            result[i] = resolved;
        }
        return result;
    } catch (Throwable t) {
        // Any runtime exception results in null
        return null;
    }
}

