public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    try {
        if (!(genericType instanceof ParameterizedType)) {
            return null;
        }
        ParameterizedType paramType = (ParameterizedType) genericType;
        Class<?> rawType = (Class<?>) paramType.getRawType();

        Type[] actualTypes = null;
        Class<?> current = targetType;
        while (current != null && actualTypes == null) {
            // Check superclass
            Type superType = current.getGenericSuperclass();
            if (superType instanceof ParameterizedType) {
                ParameterizedType sp = (ParameterizedType) superType;
                if (sp.getRawType() == rawType) {
                    actualTypes = sp.getActualTypeArguments();
                    break;
                }
            }
            // Check interfaces
            for (Type iface : current.getGenericInterfaces()) {
                if (iface instanceof ParameterizedType) {
                    ParameterizedType ip = (ParameterizedType) iface;
                    if (ip.getRawType() == rawType) {
                        actualTypes = ip.getActualTypeArguments();
                        break;
                    }
                }
            }
            current = current.getSuperclass();
        }

        if (actualTypes == null) {
            return null;
        }

        Class<?>[] result = new Class<?>[actualTypes.length];
        for (int i = 0; i < actualTypes.length; i++) {
            Type t = actualTypes[i];
            if (t instanceof Class<?>) {
                result[i] = (Class<?>) t;
            } else if (t instanceof ParameterizedType) {
                // Use the raw type if it's a class
                Type raw = ((ParameterizedType) t).getRawType();
                if (raw instanceof Class<?>) {
                    result[i] = (Class<?>) raw;
                } else {
                    result[i] = null;
                }
            } else {
                result[i] = null; // type variable or other cannot be resolved
            }
        }
        return result;
    } catch (Exception e) {
        // In case of any unexpected reflection error, fail gracefully
        return null;
    }
}

