    // Link the new bucket
    bucket.prev = prev;
    bucket.next = next;
    // Update the surrounding buckets
    if (prev != null) {
        prev.next = bucket;
    }
    // this bucket becomes the next after the inserted bucket
    this.prev = bucket;
}

