public Mappings diffStructure(String tableName, Mappings mappings) {
    if (tableName == null || tableName.isEmpty()) {
        throw new IllegalArgumentException("Table name must not be null or empty");
    }
    if (mappings == null) {
        throw new IllegalArgumentException("Mappings must not be null");
    }
    try {
        // Retrieve the current mappings for the index from Elasticsearch
        GetMappingsRequest request = new GetMappingsRequest();
        request.indices(tableName);
        GetMappingsResponse response = client.indices().getMapping(request, RequestOptions.DEFAULT);
        Map<String, MappingMetaData> currentIndices = response.mappings();
        MappingMetaData currentMeta = currentIndices.get(tableName);
        if (currentMeta == null) {
            return new Mappings(); // nothing to diff
        }

        // Current index properties (excluding _source)
        Map<String, Object> currentProps = new HashMap<>(currentMeta.getSourceAsMap());
        currentProps.remove("_source");

        // Input mapping properties
        Map<String, Object> inputProps = mappings.getSourceAsMap();

        // Build diff: fields present in current but missing in input
        Mappings diff = new Mappings();
        for (Map.Entry<String, Object> entry : currentProps.entrySet()) {
            String field = entry.getKey();
            if (!inputProps.containsKey(field)) {
                diff.put(field, entry.getValue());
            }
        }
        return diff;
    } catch (Exception e) {
        throw new RuntimeException("Failed to compute diff structure", e);
    }
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    if (mappings == null) {
        return null; // nothing to diff
    }
    try {
        // Create a new Mappings instance to hold the diff
        Mappings diff = new Mappings();
        // Iterate over the supplied mappings
        for (Object keyObj : mappings.keySet()) {
            String key = keyObj.toString();
            // Skip the _source configuration
            if ("_source".equalsIgnoreCase(key)) {
                continue;
            }
            // Add the field and its mapping to the result
            diff.put(key, mappings.get(key));
        }
        return diff;
    } catch (Exception e) {
        // In case of any unexpected error, log and return null
        System.err.println("Failed to compute mapping diff: " + e.getMessage());
        return null;
    }
}

