public Mappings diffStructure(String tableName, Mappings mappings) {
    if (mappings == null) {
        return new Mappings(); // return empty mapping when history is null
    }
    Mappings diff = new Mappings();
    try {
        // Treat Mappings as a Map<String, Object> for diff purposes
        java.util.Map<String, Object> map = (java.util.Map<String, Object>) (Object) mappings;
        for (java.util.Map.Entry<String, Object> entry : map.entrySet()) {
            String key = entry.getKey();
            // Skip _source configuration
            if ("_source".equals(key)) {
                continue;
            }
            // Only include fields that are not already present in the input map
            // (here we just copy them as the input mapping is the history map itself)
            if (!map.containsKey(key)) {
                diff.put(key, entry.getValue());
            }
        }
    } catch (ClassCastException e) {
        // Unable to cast Mappings to a Map; return empty diff
    } catch (Exception e) {
