public Mappings diffStructure(String tableName, Mappings mappings) {
    try {
        if (tableName == null || tableName.isEmpty() || mappings == null) {
            return new Mappings();
        }
        // Retrieve the desired mapping configuration for the table.
        Mappings desired = MappingProvider.getMappingForTable(tableName);
        if (desired == null) {
            return new Mappings();
        }
        Map<String, Object> desiredMap = desired.getMappings();
        Map<String, Object> currentMap = mappings.getMappings();
        if (desiredMap == null) {
            return new Mappings();
        }
        Map<String, Object> diffMap = new HashMap<>();
        for (Map.Entry<String, Object> entry : desiredMap.entrySet()) {
            String key = entry.getKey();
            if ("_source".equals(key)) {
                continue; // Skip _source config to avoid conflicts.
            }
            if (!currentMap.containsKey(key)) {
                diffMap.put(key, entry.getValue());
            }
        }
        return new Mappings(diffMap);
    } catch (Exception e) {
        // If an error occurs, return an empty mapping to avoid propagating exceptions.
        return new Mappings();
    }
}

