public void put(LoggingEvent o){
    if (o == null) {
        return;
    }
    try{
        LoggingEvent event = o.getCopy();
        if (appenderSize == maxBufferSize){
            // Buffer full: silently drop
            return;
        }
        appenderBuffer[head] = event;
        head = (head + 1) % maxBufferSize;
        appenderSize++;
    }catch (Exception e){
        // silently drop on any exception
    }
}

public void put(LoggingEvent o){
    // if buffer is full, silently drop the event
    if (size_ == capacity_)
        return;
    buffer_[writeIndex_] = o;
    writeIndex_ = (writeIndex_ + 1) % capacity_;
    size_++;
}

public void put(LoggingEvent o){
    if (o == null) {
        // silently drop null events
        return;
    }
    synchronized (this) {
        try {
            // If the internal buffer hasn't been initialized, drop the event
            if (buffer == null) {
                return;
            }
            // If buffer is full, silently drop the event
            if (count == capacity) {
                return;
            }
            buffer[tail] = o;
            tail = (tail + 1) % capacity;
            count++;
        } catch (RuntimeException e) {
            // Silently drop any runtime errors that occur while inserting
        }
    }
}

