public void put(LoggingEvent o) {
    // Null events are silently ignored
    if (o == null) {
        return;
    }
    // If the buffer is full, the event is silently dropped
    if (size == capacity) {
        return;
    }
    // Insert the event at the current write index
    buffer[writeIndex] = o;
    // Advance the write index in a circular fashion
    writeIndex = (writeIndex + 1) % capacity;
    // Increment the count of events in the buffer
    size++;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalStateException("FETCH_DATA_DURATION must be positive");
    }
    if (start > end) {
        throw new IllegalArgumentException("start must not be greater than end");
    }
    List<TimeRange> ranges = new ArrayList<>();
    long currentStart = start;
    while (currentStart < end) {
        long currentEnd = Math.min(currentStart + FETCH_DATA_DURATION, end);
        ranges.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start,long end){
    if (start < 0 || end < 0) throw new IllegalArgumentException("Start and end must be non‑negative");
    if (start > end) throw new IllegalArgumentException("Start must not be greater than end");
    List<TimeRange> ranges = new ArrayList<>();
    long current = start;
    while (current < end) {
        long remaining = end - current;
        long next;
        if (remaining <= FETCH_DATA_DURATION) {
            next = end;
        } else {
            // guard against overflow
            long maxAdd = Long.MAX_VALUE - current;
            if (FETCH_DATA_DURATION > maxAdd) {
                next = end;
            } else {
                next = current + FETCH_DATA_DURATION;
            }
        }
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    if (start > end) {
        throw new IllegalArgumentException("Start time must be less than or equal to end time");
    }
    long maxDuration = FETCH_DATA_DURATION;
    long current = start;
    while (current < end) {
        long next;
        if (current > Long.MAX_VALUE - maxDuration) {
            next = end;
        } else {
            next = Math.min(current + maxDuration, end);
        }
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    try {
        if (start >= end) {
            return ranges;
        }
        if (FETCH_DATA_DURATION <= 0) {
            throw new IllegalArgumentException("FETCH_DATA_DURATION must be positive");
        }
        long currentStart = start;
        while (currentStart < end) {
            long currentEnd = Math.min(currentStart + FETCH_DATA_DURATION, end);
            ranges.add(new TimeRange(currentStart, currentEnd));
            currentStart = currentEnd;
        }
    } catch (Exception e) {
        // Log or rethrow as unchecked if desired
        throw new RuntimeException("Failed to build time ranges", e);
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    // Ensure we have a valid range
    if (start < 0) {
        start = 0;
    }
    if (start > end) {
        // Swap if parameters are reversed
        long tmp = start;
        start = end;
        end = tmp;
    }
    List<TimeRange> result = new ArrayList<>();
    // Split the range into smaller chunks of size < FETCH_DATA_DURATION
    for (long s = start; s <= end; s += FETCH_DATA_DURATION) {
        long e = Math.min(s + FETCH_DATA_DURATION - 1, end);
        result.add(new TimeRange(s, e));
    }
    return result;
}

