static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    if (timeBucket <= 0) {
        throw new IllegalArgumentException("timeBucket must be positive");
    }
    long year = timeBucket / 10000;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;
    if (day <= 0) {
        throw new IllegalArgumentException("day part of timeBucket must be positive");
    }
    long newDay = ((day - 1) / dayStep) * dayStep + 1;
    // Ensure newDay does not exceed month length for safety; clamp to 31 if necessary
    if (newDay > 31) {
        newDay = 31;
    }
    return year * 10000 + month * 100 + newDay;
}

static long compressTimeBucket(long timeBucket,int dayStep){
    // Guard against invalid dayStep to avoid division by zero
    if(dayStep <= 0) {
        return timeBucket;
    }
    // Extract the day part (last two digits)
    long dayLong = timeBucket % 100;
    if(dayLong < 0) {
        dayLong += 100; // normalize negative modulo
    }
    int day = (int) dayLong;
    // If day is not a valid calendar day, return the original bucket
    if(day < 1 || day > 31) {
        return timeBucket;
    }
    // Calculate the start day of the segment defined by dayStep
    int startDay = ((day - 1) / dayStep) * dayStep + 1;
    // Reconstruct the compressed time bucket
    long yearMonth = timeBucket - dayLong; // zero out the day portion
    return yearMonth + startDay;
}

