    }
    if(index < 0 || len < 0 || index > str.length() || index + len > str.length()){
        throw new IndexOutOfBoundsException("Invalid index or length");
    }
    int end = index + len;
    int byteCount = 0;
    for(int i = index; i < end; i++){
        char ch = str.charAt(i);
        if(Character.isHighSurrogate(ch) && i + 1 < end
                && Character.isLowSurrogate(str.charAt(i + 1))){
            // Surrogate pair -> code point
            int codePoint = Character.toCodePoint(ch, str.charAt(i + 1));
            i++; // skip low surrogate
            byteCount += (codePoint <= 0xFFFF) ? 3 : 4; // codePoint after toCodePoint is always >0xFFFF
        } else {
            int codePoint = ch;
            if(codePoint < 0x80){
                byteCount += 1;
            } else if(codePoint < 0x800){
                byteCount += 2;
            } else {
                byteCount += 3;
            }
        }
    }
    return byteCount;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("String is null");
    }
    final int strLen = str.length();
    if (index < 0 || len < 0 || index + len > strLen) {
        throw new IndexOutOfBoundsException("index=" + index + ", len=" + len + ", str.length()=" + strLen);
    }

    int byteCount = 0;
    int i = index;
    final int end = index + len;
    while (i < end) {
        final char ch = str.charAt(i);
        if (ch <= 0x007F) {
            byteCount += 1;
        } else if (ch <= 0x07FF) {
            byteCount += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 < end) {
                final char low = str.charAt(i + 1);
                if (Character.isLowSurrogate(low)) {
                    byteCount += 4;
                    i++; // consume low surrogate
                } else {
                    // high surrogate not followed by low surrogate
                    throw new IllegalArgumentException("Invalid surrogate pair at index " + i);
                }
            } else {
                // high surrogate at end of range
                throw new IllegalArgumentException("High surrogate without low surrogate at index " + i);
            }
        } else if (Character.isLowSurrogate(ch)) {
            // low surrogate without preceding high surrogate
            throw new IllegalArgumentException("Isolated low surrogate at index " + i);
        } else {
            byteCount += 3;
        }
        i++;
    }
    return byteCount;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("str");
    }
    final int strLen = str.length();
    if (index < 0 || len < 0 || index + len > strLen) {
        throw new IndexOutOfBoundsException();
    }
    int size = 0;
    int pos = index;
    int end = index + len;
    while (pos < end) {
        char ch = str.charAt(pos++);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (pos < end) {
                char low = str.charAt(pos);
                if (Character.isLowSurrogate(low)) {
                    size += 4;   // 4 bytes for surrogate pair
                    pos++;       // consume low surrogate
                    continue;
                }
            }
            // malformed surrogate (unexpected end or missing low surrogate)
            size += 3; // treat as replacement character
        } else if (Character.isLowSurrogate(ch)) {
            // orphan low surrogate
            size += 3;
        } else {
            size += 3;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Invalid index/length for the given string");
    }

    int utf8Len = 0;
    int end = index + len;
    int i = index;

    while (i < end) {
        char ch = str.charAt(i);

        if (ch <= 0x007F) {                     // U+0000 to U+007F
            utf8Len += 1;
        } else if (ch <= 0x07FF) {               // U+0080 to U+07FF
            utf8Len += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 >= end) {
                throw new IllegalArgumentException("High surrogate at position " + i + " not followed by low surrogate");
            }
            char low = str.charAt(i + 1);
            if (!Character.isLowSurrogate(low)) {
                throw new IllegalArgumentException("High surrogate at position " + i + " not followed by low surrogate");
            }
            // Supplementary character → 4 bytes
            utf8Len += 4;
            i++;   // skip low surrogate
        } else if (Character.isLowSurrogate(ch)) {
            throw new IllegalArgumentException("Unmatched low surrogate at position " + i);
        } else {                                 // U+0800 to U+FFFF
            utf8Len += 3;
        }

        i++;
    }

    return utf8Len;
}

