public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }

    int start = 0;
    if (path.charAt(0) == '/') {
        start = 1;
    }

    int len = path.length();
    while (start < len) {
        int slash = path.indexOf('/', start);
        String seg;
        if (slash == -1) {
            seg = path.substring(start);
            start = len;
        } else {
            seg = path.substring(start, slash);
            start = slash + 1;
        }

        if (decode) {
            try {
                seg = java.net.URLDecoder.decode(seg, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (IllegalArgumentException | java.io.UnsupportedEncodingException e) {
                // UTF-8 is always supported; rethrow as unchecked if it somehow fails
                throw new RuntimeException("Error decoding path segment", e);
            }
        }

        segments.add(new PathSegmentImpl(seg));
    }

    return segments;
}

