    if(rawPath==null || rawPath.isEmpty()){
        return new ArrayList<>();
    }
    // Strip leading '/' if present for absolute paths
    if(rawPath.startsWith("/")){
        rawPath = rawPath.substring(1);
    }
    // If path became empty after stripping, return empty list
    if(rawPath.isEmpty()){
        return new ArrayList<>();
    }
    String[] rawSegments = rawPath.split("/");
    List<PathSegmentImpl> segments = new ArrayList<>(rawSegments.length);
    for(String rawSeg : rawSegments){
        if(rawSeg.isEmpty()){
            continue; // skip empty segments resulting from '//' 
        }
        String seg = rawSeg;
        if(decode){
            try{
                seg = java.net.URLDecoder.decode(rawSeg, "UTF-8");
            }catch(UnsupportedEncodingException e){
                // UTF-8 should always be supported, wrap as unchecked
                throw new RuntimeException(e);
            }
        }
        segments.add(new PathSegmentImpl(seg));
    }
    return segments;
}

