public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("DataOutput must not be null");
    }
    if (node == null) {
        return 0;
    }
    int totalSize = 0;
    LinkedBuffer current = node;
    while (current != null) {
        // Write the bytes that are valid in this buffer segment
        byte[] buffer = current.data;
        int start = current.start;
        int end = current.end;
        int length = end - start;
        out.write(buffer, start, length);
        totalSize += length;
        current = current.next;
    }
    return totalSize;
}

