        // Assume the LinkedBuffer provides getters for its internal array and size
        byte[] buf = current.getBuffer();
        int len = current.getSize();
        if (buf != null && len > 0) {
            out.write(buf, 0, len);
            totalSize += len;
        }
        // Move to the next buffer in the chain if available
        current = current.getNext();
    }
    return totalSize;
}

