public String format(final LoggingEvent event){
    try{
        if(event==null){
            return "";
        }
        StringBuilder sb=new StringBuilder();
        // Timestamp
        long time=event.getTimeStamp();
        java.text.SimpleDateFormat sdf=new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
        sb.append(sdf.format(new java.util.Date(time))).append(' ');
        // Thread name
        sb.append('[').append(event.getThreadName()).append("] ");
        // Level
        sb.append(event.getLevel()).append(' ');
        // Logger name
        sb.append(event.getLoggerName()).append(" - ");
        // Message
        sb.append(String.valueOf(event.getMessage()));
        // Throwable (if any)
        if(event.getThrowableInformation()!=null){
            java.lang.Throwable t=event.getThrowableInformation().getThrowable();
            if(t!=null){
                sb.append(System.lineSeparator()).append(t.toString());
                for(StackTraceElement ste:t.getStackTrace()){
                    sb.append(System.lineSeparator()).append("\tat ").append(ste.toString());
                }
            }
        }
        return sb.toString();
    }catch(Exception e){
        return "";
    }
}

