@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (value == null) {
        return null;
    }
    // Ensure the target type is Character or a superclass thereof
    if (!Character.class.isAssignableFrom(type)) {
        throw new IllegalArgumentException("Unsupported target type: " + type);
    }

    // Already a Character instance
    if (value instanceof Character) {
        return value;
    }

    // String representation: should be exactly one character
    if (value instanceof String) {
        String s = (String) value;
        if (s.length() == 1) {
            return s.charAt(0);
        } else {
            throw new IllegalArgumentException("Cannot convert String to Character: length != 1");
        }
    }

    // Numeric value: interpret its int value as a Unicode code point
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        return (char) intVal;
    }

    // Fallback: cannot convert
    throw new IllegalArgumentException(
        "Cannot convert value of type " + value.getClass().getName() + " to Character");
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (!(Character.class.equals(type) || char.class.equals(type))) {
        throw new IllegalArgumentException("Unsupported target type: " + type);
    }
    if (value == null) {
        return null;
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof CharSequence) {
        CharSequence cs = (CharSequence) value;
        if (cs.length() == 0) {
            throw new Exception("Cannot convert empty CharSequence to Character");
        }
        return Character.valueOf(cs.charAt(0));
    }
    if (value instanceof String) {
        String s = (String) value;
        if (s.length() != 1) {
            throw new Exception("String length != 1: " + s);
        }
        return Character.valueOf(s.charAt(0));
    }
    if (value instanceof Number) {
        int codePoint = ((Number) value).intValue();
        return Character.valueOf((char) codePoint);
    }
    if (value instanceof char[]) {
        char[] arr = (char[]) value;
        if (arr.length == 0) {
            throw new Exception("Cannot convert empty char[] to Character");
        }
        return Character.valueOf(arr[0]);
    }
    throw new Exception("Cannot convert value of type " + value.getClass() + " to Character");
}

@Override protected Object convertToType(final Class<?> type,final Object value) throws Exception {
    // Allow both primitive char and its wrapper Character
    if (type == null) {
        throw new Exception("Target type is null");
    }
    // If the caller explicitly requested a Character or char type
    if (type == Character.class || type == char.class) {
        if (value == null) {
            // Null is considered a valid conversion to null
            return null;
        }
        if (value instanceof Character) {
            return value;
        }
        if (value instanceof String) {
            String str = (String) value;
            if (str.length() == 1) {
                return Character.valueOf(str.charAt(0));
            } else if (str.isEmpty()) {
                // Empty string cannot be converted to a character
                throw new Exception("Cannot convert empty string to a Character");
            } else {
                throw new Exception("Cannot convert string with length > 1 to a Character");
            }
        }
        if (value instanceof Number) {
            // Numeric values are converted using intValue() as the underlying character code
            return Character.valueOf((char) ((Number) value).intValue());
        }
        // Unsupported type conversion
        throw new Exception("Cannot convert type " + value.getClass().getName() + " to a Character");
    }
    // If the requested type is not a char/Character, defer to superclass or throw
    throw new Exception("Unsupported target type: " + type.getName());
}

@Override protected Object convertToType(final Class<?> type,final Object value) throws Exception {
    // Return null for null input
    if (value == null) {
        return null;
    }
    // Ensure the target type is Character (class or primitive)
    if (!(type == Character.class || type == char.class)) {
        throw new IllegalArgumentException("Target type must be java.lang.Character or char");
    }
    // Directly return if already a Character
    if (value instanceof Character) {
        return value;
    }
    // Handle String: must be single character
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0); // auto-box to Character
        } else {
            throw new IllegalArgumentException("String for Character conversion must be exactly one character long");
        }
    }
    // Handle numeric types: convert numeric value to char if within range
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal >= Character.MIN_VALUE && intVal <= Character.MAX_VALUE) {
            return (char) intVal; // auto-box to Character
        } else {
            throw new IllegalArgumentException("Numeric value out of Character range");
        }
    }
    // Unsupported conversion source
    throw new IllegalArgumentException(
        "Cannot convert value of type " + value.getClass().getName() + " to java.lang.Character"
    );
}

protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == Character.class || type == char.class) {
        if (value == null) {
            return null;
        }
        if (value instanceof Character) {
            return value;
        }
        if (value instanceof String) {
            String str = (String) value;
            if (str.length() == 1) {
                return str.charAt(0);
            }
        }
        if (value instanceof Number) {
            return (char) ((Number) value).intValue();
        }
        throw new IllegalArgumentException("Cannot convert value to Character: " + value);
    }
    throw new IllegalArgumentException("Unsupported target type: " + type);
}

