    java.util.HashSet<Character> searchChars = new java.util.HashSet<>();
    for (String s : searchStrArray) {
        if (s == null) continue;
        for (int i = 0; i < s.length(); i++) {
            searchChars.add(Character.toLowerCase(s.charAt(i)));
        }
