public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) return 2;
    int candidate = desiredCapacity;
    // Ensure candidate is odd
    if ((candidate & 1) == 0) candidate++;
    while (true) {
        boolean isPrime = true;
        int limit = (int) Math.sqrt(candidate);
        for (int i = 3; i <= limit; i += 2) {
            if (candidate % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) return candidate;
        // Avoid integer overflow
        if (candidate > Integer.MAX_VALUE - 2) return candidate;
        candidate += 2; // skip even numbers
    }
}

public static int nextPrime(int desiredCapacity) {
    try {
        // Treat negative or zero input as 2 (the smallest prime)
        if (desiredCapacity <= 2) {
            return 2;
        }

        int candidate = desiredCapacity;

        // Ensure candidate is odd (even numbers > 2 cannot be prime)
        if (candidate % 2 == 0) {
            candidate++;
        }

        while (true) {
            // Check for primality
            boolean isPrime = true;
            int limit = (int) Math.sqrt(candidate);
            for (int i = 3; i <= limit; i += 2) {
                if (candidate % i == 0) {
                    isPrime = false;
                    break;
                }
            }

            if (isPrime) {
                return candidate;
            }

            // Move to next odd candidate
            candidate += 2;

            // Avoid potential integer overflow
            if (candidate <= 0) { // overflow occurred
                return Integer.MAX_VALUE;
            }
