public final byte[] toByteArray(){
    if (buffer == null) return new byte[0];
    try{
        ByteBuffer dup = buffer.duplicate();
        dup.flip();                           // prepare for reading from start
        byte[] result = new byte[dup.remaining()];
        dup.get(result);
        return result;
    }catch (IllegalStateException e){
        throw new RuntimeException("Failed to read buffer contents", e);
    }
}

public final byte[] toByteArray() {
    // If no buffers were added, return an empty array
    if (buffers == null || buffers.isEmpty()) {
        return new byte[0];
    }

    // Compute the total size of data written to all buffers
    int totalSize = 0;
    for (ByteBuffer bb : buffers) {
        if (bb != null) {
            // The remaining bytes are the ones written to this buffer
            totalSize += bb.remaining();
        }
    }

    byte[] result = new byte[totalSize];
    int offset = 0;

    // Copy each buffer's content to the result array
    for (ByteBuffer bb : buffers) {
        if (bb != null && bb.remaining() > 0) {
            // Duplicate to avoid changing the original buffer's state
            ByteBuffer dup = bb.duplicate();
            dup.flip(); // Prepare for read from the start to current position
            int len = dup.remaining();
            dup.get(result, offset, len);
            offset += len;
        }
    }

    return result;
}

