public final byte[] toByteArray(){
    if (content == null) {
        return new byte[0];
    }
    try {
        // If the buffer is backed by an array and the array is exactly the data we want
        if (content.hasArray() &&
            content.position() == content.limit() &&
            content.arrayOffset() == 0) {
            // Duplicate the array to avoid exposing internal state
            return java.util.Arrays.copyOf(content.array(), content.limit());
        } else {
            // Create a new array from the remaining bytes
            byte[] result = new byte[content.remaining()];
            int oldPos = content.position();
            content.rewind();
            content.get(result);
            content.position(oldPos);
            return result;
        }
    } catch (Exception ex) {
        // Fallback: duplicate the buffer and extract bytes
        ByteBuffer dup = content.duplicate();
        dup.flip();
        byte[] result = new byte[dup.remaining()];
        dup.get(result);
        return result;
    }
}

