            return new byte[0];
        }
        int start = content.position();
        int end = content.limit();
        int length = end - start;
        byte[] result = new byte[length];
        ByteBuffer duplicate = content.duplicate();
        duplicate.position(start);
        duplicate.limit(end);
        duplicate.get(result);
        return result;
    } catch (RuntimeException e) {
        throw new IllegalStateException("Unable to convert buffer contents to byte array", e);
    }
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= str.length()) {
                sb.append('\\');
                continue;
            }
            char next = str.charAt(i + 1);
            // handle escaped backslash first
            if (next == '\\') {
                sb.append('\\');
                i++; // skip the second backslash
                continue;
            }
            switch (next) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case 'u':
                    if (i + 6 <= str.length()) {
                        String hex = str.substring(i + 2, i + 6);
                        try {
                            int code = Integer.parseInt(hex, 16);
                            sb.append((char) code);
                            i += 5; // advance past \uXXXX (4 hex digits + backslash and 'u')
                            continue;
                        } catch (NumberFormatException e) {
                            throw new IllegalArgumentException("Invalid Unicode escape: \\u" + hex);
                        }
                    } else {
                        throw new IllegalArgumentException("Incomplete Unicode escape sequence");
                    }
                default:
                    // check for octal escape (up to three octal digits)
                    if (next >= '0' && next <= '7') {
                        int j = i + 1;
                        int val = 0;
                        int count = 0;
                        while (j < str.length() && count < 3) {
                            char ch = str.charAt(j);
                            if (ch >= '0' && ch <= '7') {
                                val = (val << 3) + (ch - '0');
                                j++;
                                count++;
                            } else {
                                break;
                            }
                        }
                        sb.append((char) val);
                        i = j - 1; // adjust for loop increment
                        continue;
                    } else {
                        // unrecognized escape, keep the char as is
                        sb.append(next);
                    }
                    break;
            }
            i++; // skip escape character
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

