private int computeBinaryLog(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    // The number of bits required to represent n in binary is the position
    // of the highest set bit. Java's Integer.numberOfLeadingZeros gives
    // the count of zero bits before the first one, so we subtract that
    // from the total number of bits in an int (32) to get the bit length.
    return 32 - Integer.numberOfLeadingZeros(n);
}

