public double vertexWeight(Set<V> v){
    double sum = 0.0;
    if (v == null || v.isEmpty()){
        return sum;
    }
    for (V element : v){
        if (element == null){
            continue;
        }
        try{
            // If element implements a getWeight() method returning a numeric type
            java.lang.reflect.Method m = element.getClass().getMethod("getWeight");
            Object res = m.invoke(element);
            if (res instanceof Number){
                sum += ((Number)res).doubleValue();
            }
        }catch (NoSuchMethodException | IllegalAccessException | java.lang.reflect.InvocationTargetException ignored){
            // Ignore elements without a getWeight method
            if (element instanceof Number){
                sum += ((Number)element).doubleValue();
            }
        }
    }
    return sum;
}

