public byte[] toByteArray(){
    try {
        if (content == null) {
            return new byte[0];
        }
        int pos = content.position();
        int lim = content.limit();
        byte[] bytes = new byte[lim - pos];
        content.get(bytes);
        content.position(pos); // restore original position
        return bytes;
    } catch (Exception e) {
        // Fallback: return empty array if any exception occurs
        return new byte[0];
    }
}

public byte[] toByteArray(){
    // Guard against null internal buffer
    if (buf == null) {
        return new byte[0];
    }
    // Determine the number of unread bytes
    int size = count - pos;
    if (size <= 0) {
        return new byte[0];
    }
    byte[] result = new byte[size];
    try {
        // Safe array copy of the unread portion
        System.arraycopy(buf, pos, result, 0, size);
    } catch (ArrayIndexOutOfBoundsException e) {
        // Fallback: copy only the part that fits in the buffer
        int safeSize = Math.min(buf.length - pos, size);
        if (safeSize > 0) {
            result = new byte[safeSize];
            System.arraycopy(buf, pos, result, 0, safeSize);
        } else {
            result = new byte[0];
        }
    }
    return result;
}

public byte[] toByteArray() {
    try {
        if (content == null) {
            return new byte[0];
        }
        if (content.hasArray()) {
            int pos = content.position();
            int limit = content.limit();
            int size = limit - pos;
            byte[] copy = new byte[size];
            System.arraycopy(content.array(), content.arrayOffset() + pos, copy, 0, size);
            return copy;
        } else {
            byte[] copy = new byte[content.remaining()];
            content.duplicate().get(copy);
            return copy;
        }
    } catch (Exception e) {
        return new byte[0];
    }
}

