protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return new GraphWalk<>(graph, null, null, 0.0, Collections.emptyList());
    }
    // Build adjacency mapping from vertices to incident edges
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour) {
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(src, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(tgt, k -> new ArrayList<>()).add(e);
    }
    // Pick a start vertex (source of first edge)
    Iterator<E> it = tour.iterator();
    E firstEdge = it.next();
    V startVertex = graph.getEdgeSource(firstEdge);
    V currentVertex = startVertex;
    List<E> orderedEdges = new ArrayList<>(tour.size());
    Set<E> remaining = new HashSet<>(tour);
    double totalWeight = 0.0;
    while (!remaining.isEmpty()) {
        List<E> edgesAtCurrent = adjacency.get(currentVertex);
        if (edgesAtCurrent == null) {
            throw new IllegalArgumentException("Graph is not connected or tour is invalid");
        }
        boolean found = false;
        for (E e : edgesAtCurrent) {
            if (!remaining.contains(e)) continue;
            // Append this edge to the path
            orderedEdges.add(e);
            remaining.remove(e);
            totalWeight += graph.getEdgeWeight(e);
            // Move to the adjacent vertex
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            currentVertex = src.equals(currentVertex) ? tgt : src;
            found = true;
            break;
        }
        if (!found) {
            throw new IllegalArgumentException("Cannot traverse remaining edges; tour may be disconnected");
        }
    }
    V endVertex = currentVertex;
    return new GraphWalk<>(graph, startVertex, endVertex, totalWeight, orderedEdges);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null || tour.isEmpty()){
        return null;
    }
    // Convert the set to a list to allow ordered traversal (arbitrary order)
    List<E> edgeList = new ArrayList<>(tour);
    // Determine start vertex from the first edge
    E firstEdge = edgeList.get(0);
    V start = graph.getEdgeSource(firstEdge);
    // Determine end vertex from the last edge (may not form a perfect path but gives a valid GraphPath)
    E lastEdge = edgeList.get(edgeList.size() - 1);
    V end = graph.getEdgeTarget(lastEdge);
    // Sum edge weights (assuming graph provides getEdgeWeight)
    double totalWeight = 0.0;
    for (E e : edgeList) {
        double w = graph.getEdgeWeight(e);
        totalWeight += Double.isNaN(w) ? 0.0 : w;
    }
    // Construct and return the path
    return new DefaultGraphPath<>(graph, start, end, edgeList, totalWeight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (graph == null || tour == null || tour.isEmpty()) {
        throw new IllegalArgumentException("graph and tour must be non‑null and non‑empty");
    }
    // copy remaining edges to modify
    Set<E> remaining = new HashSet<>(tour);
    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();

    // start from an arbitrary edge
    E start = remaining.iterator().next();
    V current = graph.getEdgeSource(start);
    vertices.add(current);
    edges.add(start);
    remaining.remove(start);

    // walk through remaining edges creating a continuous path
    while (!remaining.isEmpty()) {
        boolean found = false;
        Iterator<E> it = remaining.iterator();
        while (it.hasNext()) {
            E e = it.next();
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(current)) {
                current = tgt;
                vertices.add(current);
                edges.add(e);
                it.remove();
                found = true;
                break;
            } else if (tgt.equals(current)) {
                current = src;
                vertices.add(current);
                edges.add(e);
                it.remove();
                found = true;
                break;
            }
        }
        if (!found) {
            throw new IllegalArgumentException("Provided edge set does not form a continuous tour");
        }
    }

    // Return an anonymous implementation of GraphPath
    return new GraphPath<V,E>() {
        @Override public Graph<V,E> getGraph() { return graph; }
        @Override public V getStartVertex() { return vertices.get(0); }
        @Override public V getEndVertex() { return vertices.get(vertices.size() - 1); }
        @Override public List<E> getEdgeList() { return edges; }
        @Override public List<V> getVertexList() { return vertices; }
        @Override public double getLength() { return 0; }
        @Override public double getWeight() { return 0; }
    };
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || tour.isEmpty()) {
        return null;
    }
    // Use a LinkedHashSet to preserve insertion order
    Set<E> remaining = new LinkedHashSet<>(tour);
    // Choose an arbitrary starting edge
    E firstEdge = remaining.iterator().next();
    V start = graph.getEdgeSource(firstEdge);
    V current = start;

    List<E> edgeList = new ArrayList<>();
    List<V> vertexList = new ArrayList<>();
    vertexList.add(current);

    // Remove first edge and add to list
    remaining.remove(firstEdge);
    edgeList.add(firstEdge);
    // Move to the next vertex along the first edge
    current = graph.getEdgeTarget(firstEdge);
    vertexList.add(current);

    while (!remaining.isEmpty()) {
        E nextEdge = null;
        for (E e : remaining) {
            V source = graph.getEdgeSource(e);
            V target = graph.getEdgeTarget(e);
            if (source.equals(current) || target.equals(current)) {
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null) {
            throw new IllegalArgumentException(
                    "Tour is not a connected path; cannot find next edge for vertex: " + current);
        }
        edgeList.add(nextEdge);
        remaining.remove(nextEdge);
        V nextVertex = graph.getEdgeSource(nextEdge).equals(current)
                ? graph.getEdgeTarget(nextEdge)
                : graph.getEdgeSource(nextEdge);
        vertexList.add(nextVertex);
        current = nextVertex;
    }

    // Compute total weight of the path
    double weight = 0.0;
    for (E e : edgeList) {
        weight += graph.getEdgeWeight(e);
    }

    // Construct and return the GraphPath
    return new DefaultGraphPath<>(graph, vertexList, edgeList, weight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    try {
        if (tour == null || graph == null) {
            return null;
        }
        java.util.List<E> edgeList = new java.util.ArrayList<>(tour);
        if (edgeList.isEmpty()) {
            return new org.jgrapht.graph.DefaultGraphPath<>(graph,
                                                             new java.util.ArrayList<>(),
                                                             new java.util.ArrayList<>());
        }
        E first = edgeList.get(0);
        V source = graph.getEdgeSource(first);
        V target = graph.getEdgeTarget(first);
        return new org.jgrapht.GraphWalk<>(graph, source, target, edgeList);
    } catch (Exception ignored) {
        return null;
    }
}

