int addConstantNameAndType(final String name, final String descriptor) {
    // Validate input
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("name and descriptor must not be null");
    }

    // Lazily initialize the constant pool if necessary
    if (constantPool == null) {
        constantPool = new java.util.ArrayList<Symbol>();
    }

    // Check if an equivalent CONSTANT_NameAndType_info already exists
    for (int i = 0; i < constantPool.size(); i++) {
        Symbol s = constantPool.get(i);
        if (s instanceof ConstantNameAndTypeInfo) {
            ConstantNameAndTypeInfo existing = (ConstantNameAndTypeInfo) s;
            if (name.equals(existing.getName()) && descriptor.equals(existing.getDescriptor())) {
                return i; // Return the existing index
            }
        }
    }

    // No existing entry found – create and add a new one
    ConstantNameAndTypeInfo newConst = new ConstantNameAndTypeInfo(name, descriptor);
    constantPool.add(newConst);

    return constantPool.size() - 1; // Return index of the newly added entry
}

