    if (bounds == null) {
        return Pair.of(Collections.emptyList(), 0L);
    }
    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    long cumulativeSum = 0L;
    for (int i = n - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        if (val == null) {
            throw new IllegalArgumentException("bounds list contains null at index " + i);
        }
        cumulativeSum += val;
        suffix.add((int) cumulativeSum);
    }
    Collections.reverse(suffix);
    return Pair.of(suffix, cumulativeSum);
}

