    Object secondLock = System.identityHashCode(this) < System.identityHashCode(list) ? list : this;

    synchronized (firstLock) {
        synchronized (secondLock) {
            // Snapshot all nodes from the source list
            List<ListNodeImpl<E>> nodes = new ArrayList<>();
            for (ListNodeImpl<E> node : list) {
                nodes.add(node);
