    int capacity = buf.length;
    int newlen = len + 4;
    if (newlen > capacity) {
        byte[] newbuf = new byte[Math.max(newlen, capacity << 1)];
        System.arraycopy(buf, 0, newbuf, 0, len);
        this.buf = newbuf;
    }
    buf[len++] = (byte)(intValue >>> 24);
    buf[len++] = (byte)(intValue >>> 16);
    buf[len++] = (byte)(intValue >>> 8);
    buf[len++] = (byte)intValue;
    this.len = len;
    return this;
}

