    if (newLen > this.buf.length) {
        byte[] newBuf = new byte[Math.max(newLen, this.buf.length << 1)];
        System.arraycopy(this.buf, 0, newBuf, 0, this.len);
        this.buf = newBuf;
    }
    this.buf[this.len]     = (byte)(intValue >>> 24);
    this.buf[this.len + 1] = (byte)(intValue >>> 16);
    this.buf[this.len + 2] = (byte)(intValue >>> 8);
    this.buf[this.len + 3] = (byte)intValue;
    this.len = newLen;
    return this;
}

