public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Validate parameters
    if (buf == null) {
        throw new IllegalArgumentException("Buffer must not be null");
    }
    if (nameStart < 0) {
        throw new IllegalArgumentException("nameStart must be non‑negative");
    }

    // Obtain the full name.  It is assumed that the class has a suitable getter.
    String fullName = null;
    try {
        // If there is a getName() method, use it; otherwise try a field named 'name'
        java.lang.reflect.Method m = this.getClass().getMethod("getName");
        if (m != null) {
            Object res = m.invoke(this);
            if (res instanceof String) {
                fullName = (String) res;
            }
        }
    } catch (Exception e) {
        // ignore, will try a field
    }
    if (fullName == null) {
        // Attempt to read a field called 'name'
        try {
            java.lang.reflect.Field f = this.getClass().getDeclaredField("name");
            f.setAccessible(true);
            Object val = f.get(this);
            if (val instanceof String) {
                fullName = (String) val;
            }
        } catch (Exception e) {
            // no name found – nothing to abbreviate
            return;
        }
    }

    if (fullName == null || fullName.isEmpty()) {
        return; // nothing to abbreviate
    }
    if (nameStart > fullName.length()) {
        return; // start index beyond string length – nothing to do
    }

    // Prepare abbreviation
    int remaining = fullName.length() - nameStart;
    if (remaining <= 0) {
        return; // nothing to add
    }

    final int MAX_ABBREV = 30;
    if (remaining <= MAX_ABBREV) {
        // The part to abbreviate is short enough – append it in full
        buf.append(fullName.substring(nameStart));
    } else {
        // Abbreviate by keeping a prefix and suffix with an ellipsis in between
        final int PREFIX_LEN = 15;
        final int SUFFIX_LEN = 15;
        int prefixEnd = nameStart + PREFIX_LEN;
        if (prefixEnd > fullName.length() - SUFFIX_LEN) {
            // Avoid overlap – just take the longest possible substring
            prefixEnd = fullName.length() - SUFFIX_LEN;
        }
        buf.append(fullName.substring(nameStart, prefixEnd));
        buf.append("…");
        buf.append(fullName.substring(fullName.length() - SUFFIX_LEN));
    }
}

public void abbreviate(final int nameStart, final StringBuffer buf){
    if (nameStart < 0) {
        throw new IllegalArgumentException("nameStart cannot be negative");
    }
    // Assume the fully qualified name is stored in a field named 'name'.
    // Reference it safely to avoid null pointer exceptions.
    final String fullName = (this.name == null) ? "" : this.name;
    if (fullName.isEmpty() || nameStart >= fullName.length()) {
        return;
    }
    // Extract the portion we want to abbreviate.
    final String segment = fullName.substring(nameStart);
    // Split the segment by '.' characters.
    final String[] parts = segment.split("\\.");
    // Build the abbreviation: keep the last part entirely, abbreviate preceding parts.
    for (int i = 0; i < parts.length; i++) {
        if (i < parts.length - 1) {
            if (!parts[i].isEmpty()) {
                buf.append(parts[i].charAt(0)).append('.');
            }
        } else {
            buf.append(parts[i]);
        }
    }
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        throw new IllegalArgumentException("buf cannot be null");
    }
    String original = buf.toString();
    if (nameStart < 0 || nameStart > original.length()) {
        throw new IllegalArgumentException("nameStart out of bounds");
    }
    if (nameStart == original.length()) {
        return; // nothing to abbreviate
    }
    try {
        String remaining = original.substring(nameStart);
        boolean newSegment = true;
        for (int i = 0; i < remaining.length(); i++) {
            char ch = remaining.charAt(i);
            if (newSegment) {
                buf.append(ch);
                newSegment = false;
            }
            if (ch == '.' || ch == '/' || ch == '_') {
                newSegment = true;
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to abbreviate", e);
    }
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Assume the class has a field `String name` containing the full name.
    if (name == null || name.length() == 0 || buf == null) {
        return;
    }
    if (nameStart < 0 || nameStart >= name.length()) {
        return;
    }
    final int len = name.length();
    int i = nameStart;
    while (i < len) {
        // Find the next separator: '.' or '/'
        int dotIdx = name.indexOf('.', i);
        int slashIdx = name.indexOf('/', i);
        int nextSep = -1;
        if (dotIdx != -1 && slashIdx != -1) {
            nextSep = Math.min(dotIdx, slashIdx);
        } else if (dotIdx != -1) {
            nextSep = dotIdx;
        } else if (slashIdx != -1) {
            nextSep = slashIdx;
        } else {
            nextSep = len; // No more separators
        }

        // Length of the current component
        int compLen = nextSep - i;
        if (compLen > 0) {
            if (nextSep == len) {
                // Last component: append it fully
                buf.append(name, i, nextSep);
            } else {
                // Non‑last component: append the first character and a dot
                buf.append(name.charAt(i));
                buf.append('.');
            }
        }
        // Skip over the separator if present
        i = nextSep + 1;
    }
}

public static Type resolveBound(TypeVariable<?> typeVariable){
    try{
