public static Type resolveBound(TypeVariable<?> typeVariable) {
    if (typeVariable == null) {
        return Unknown.class;
    }
    try {
        Type[] bounds = typeVariable.getBounds();
        if (bounds == null || bounds.length == 0) {
            return Unknown.class;
        }
        // Look for a resolvable bound
        for (Type bound : bounds) {
            if (bound == null) {
                continue;
            }
            // Prefer concrete Class types
            if (bound instanceof Class<?>) {
                return bound;
            }
            // If the bound itself is a TypeVariable, attempt to resolve it recursively
            if (bound instanceof TypeVariable<?>) {
                Type resolved = resolveBound((TypeVariable<?>) bound);
                if (!(resolved instanceof Unknown)) {
                    return resolved;
                }
            }
            // Accept other bound types as the most direct resolution
            return bound;
        }
        return Unknown.class;
    } catch (Exception e) {
        return Unknown.class;
    }
}

private static <V,E>boolean isClique(Graph<V,E> graph,Set<V> vertices){
    if (graph == null || vertices == null) {
        return false;
    }
    int size = vertices.size();
    if (size <= 1) {
        return true; // empty or single vertex is trivially a clique
    }
    // Convert to list for indexed access
    ArrayList<V> list = new ArrayList<>(vertices);
    for (int i = 0; i < size; i++) {
        V vi = list.get(i);
        for (int j = i + 1; j < size; j++) {
            V vj = list.get(j);
            if (!graph.containsEdge(vi, vj)) {
                return false;
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    int n = vertices.size();
    if (n <= 1) {
        return true;
    }
    java.util.List<V> list = new java.util.ArrayList<>(vertices);
    try {
        for (int i = 0; i < n - 1; i++) {
            V u = list.get(i);
            if (u == null) {
                return false;
            }
            for (int j = i + 1; j < n; j++) {
                V v = list.get(j);
                if (v == null) {
                    return false;
                }
                if (!graph.containsEdge(u, v) && !graph.containsEdge(v, u)) {
                    return false;
                }
            }
        }
    } catch (IllegalArgumentException | NullPointerException e) {
        // If graph throws due to vertices not belonging to the graph or other
        // run‑time errors, treat as non‑clique.
        return false;
    }
    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (graph == null || vertices == null || vertices.isEmpty()) {
        return true; // an empty or single-vertex subgraph is trivially a clique
    }
    // Convert to list for efficient indexed access
    List<V> list = new ArrayList<>(vertices);
    int size = list.size();
    for (int i = 0; i < size - 1; i++) {
        V u = list.get(i);
        for (int j = i + 1; j < size; j++) {
            V v = list.get(j);
            try {
                if (!graph.containsEdge(u, v)) {
                    return false; // missing edge means not a clique
                }
            } catch (Exception e) {
                // Wrap any graph-related exception in a runtime exception with context
                throw new RuntimeException(
                    "Failed to determine edge existence between " + u + " and " + v, e);
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    int size = vertices.size();
    if (size < 2) {
        return true;
    }
    // Convert to a list for efficient indexed access
    List<V> vertexList = new ArrayList<>(vertices);
    for (int i = 0; i < size; i++) {
        V v1 = vertexList.get(i);
        for (int j = i + 1; j < size; j++) {
            V v2 = vertexList.get(j);
            // For undirected graphs this is sufficient.
            // If the graph is directed and a clique should be defined as
            // bidirectional edges, an additional containsEdge(v2, v1) check
            // can be added here.
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices){
    if (graph == null) throw new IllegalArgumentException("graph cannot be null");
    if (vertices == null) throw new IllegalArgumentException("vertices cannot be null");
