private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>(keys == null ? 0 : keys.size());
    if (keys == null || keys.isEmpty()) {
        return bounds;
    }

    int minVal = Integer.MAX_VALUE;
    for (K key : keys) {
        if (key instanceof Integer) {
            int v = (Integer) key;
            if (v < minVal) {
                minVal = v;
            }
        }
    }

    if (minVal == Integer.MAX_VALUE) {
        // No integer keys found; return an empty bounds list
        return bounds;
    }

    for (int i = 0; i < keys.size(); i++) {
        bounds.add(minVal);
    }
    return bounds;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    if (keys == null) {
        throw new IllegalArgumentException("keys list cannot be null");
    }
    List<Integer> result = new ArrayList<>(keys.size());
    // Defensive copy and sort the keys for binary search
    List<Integer> sorted = new ArrayList<>(keys.size());
    for (K k : keys) {
        if (k == null) {
            throw new IllegalArgumentException("key element cannot be null");
        }
        // We assume K can be cast to Integer; otherwise will throw ClassCastException
        sorted.add(((Integer) k));
    }
    Collections.sort(sorted);
    for (K k : keys) {
        int value = ((Integer) k).intValue();
        int idx = Collections.binarySearch(sorted, value);
        int lowerIdx;
        if (idx >= 0) {
            lowerIdx = idx - 1; // exact match, take preceding element
        } else {
            int insertionPoint = -idx - 1;
            lowerIdx = insertionPoint - 1;
        }
        if (lowerIdx >= 0) {
            result.add(sorted.get(lowerIdx));
        } else {
            result.add(null); // no lower bound available
        }
    }
    return result;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>();
    if (keys == null || keys.isEmpty()) {
        return lowerBounds;
    }
    try {
        TreeSet<Integer> sorted = new TreeSet<>();
        for (K k : keys) {
            sorted.add((Integer) k);
        }
        for (K k : keys) {
            Integer val = (Integer) k;
            Integer lower = sorted.lower(val);
            lowerBounds.add(lower);
        }
    } catch (ClassCastException e) {
        // If K is not Integer, return empty bounds or handle appropriately
        return lowerBounds;
    }
    return lowerBounds;
}

private List<Integer> computeLowerBounds(List<K> keys){
    java.util.List<Integer> result = new java.util.ArrayList<>(keys.size());
    java.util.List<Integer> sorted = new java.util.ArrayList<>(keys.size());
    for (K k : keys) {
        if (!(k instanceof Integer)) {
            throw new IllegalArgumentException("Key must be Integer");
        }
        sorted.add((Integer) k);
    }
    java.util.Collections.sort(sorted);
    for (K k : keys) {
        int key = ((Integer) k).intValue();
        int idx = java.util.Collections.binarySearch(sorted, key);
        int lowerIdx;
        if (idx >= 0) {
            while (idx + 1 < sorted.size() && sorted.get(idx + 1).equals(key)) {
                idx++;
            }
            lowerIdx = idx;
        } else {
            lowerIdx = -idx - 2;
        }
        if (lowerIdx >= 0) {
            result.add(sorted.get(lowerIdx));
        } else {
            result.add(null);
        }
    }
    return result;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> lowerBounds = new ArrayList<>();
    if (keys == null) {
        return lowerBounds;
    }
    for (K key : keys) {
        try {
            if (key == null) {
                // Skip null keys
                continue;
            }
            if (key instanceof Number) {
                lowerBounds.add(((Number) key).intValue());
            } else if (key instanceof Comparable) {
                // For comparable types, use hashCode to derive an integer bound
                lowerBounds.add(Math.abs(key.hashCode()));
            } else {
                // Fallback to hashCode
                lowerBounds.add(Math.abs(key.hashCode()));
            }
        } catch (Exception e) {
            // Skip problematic keys but continue processing others
            continue;
        }
    }
    return lowerBounds;
}

