private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    int i = 0;
    final int len = descriptor.length();
    // Assuming a field named outputStack that supports a pop() operation.
    if (descriptor.charAt(0) == '(') {
        i++; // skip '('
        while (i < len && descriptor.charAt(i) != ')') {
            char c = descriptor.charAt(i);
            // skip the type descriptor
            if (c == 'B' || c == 'C' || c == 'D' || c == 'F' || c == 'I' || c == 'J' || c == 'S' || c == 'Z') {
                i++;
            } else if (c == '[') {
                // array descriptor: skip all '[' and then component type
                while (i < len && descriptor.charAt(i) == '[') {
                    i++;
                }
                if (i >= len) {
                    throw new IllegalArgumentException("Incomplete array descriptor in " + descriptor);
                }
                c = descriptor.charAt(i);
                if (c == 'L') {
                    i++; // skip 'L'
                    while (i < len && descriptor.charAt(i) != ';') {
                        i++;
                    }
                    if (i >= len) {
                        throw new IllegalArgumentException("Missing ';' in object descriptor in " + descriptor);
                    }
                    i++; // skip ';'
                } else {
                    // primitive component
                    i++;
                }
            } else if (c == 'L') {
                // object descriptor
                i++; // skip 'L'
                while (i < len && descriptor.charAt(i) != ';') {
                    i++;
                }
                if (i >= len) {
                    throw new IllegalArgumentException("Missing ';' in object descriptor in " + descriptor);
                }
                i++; // skip ';'
            } else {
                throw new IllegalArgumentException("Unknown descriptor character '" + c + "' at position " + i + " in " + descriptor);
            }
            // Pop a frame from the output stack for each argument
            try {
                outputStack.pop();
            } catch (Exception e) {
                throw new IllegalStateException("Failed to pop from outputStack while processing descriptor " + descriptor, e);
            }
        }
        // We ignore the return type of the method descriptor
    } else {
        // Single type descriptor
        char c = descriptor.charAt(i);
        if (c == 'B' || c == 'C' || c == 'D' || c == 'F' || c == 'I' || c == 'J' || c == 'S' || c == 'Z') {
            i++;
        } else if (c == '[') {
            // array descriptor: skip all '[' and then component type
            while (i < len && descriptor.charAt(i) == '[') {
                i++;
            }
            if (i >= len) {
                throw new IllegalArgumentException("Incomplete array descriptor in " + descriptor);
            }
            c = descriptor.charAt(i);
            if (c == 'L') {
                i++; // skip 'L'
                while (i < len && descriptor.charAt(i) != ';') {
                    i++;
                }
                if (i >= len) {
                    throw new IllegalArgumentException("Missing ';' in object descriptor in " + descriptor);
                }
                i++; // skip ';'
            } else {
                // primitive component
                i++;
            }
        } else if (c == 'L') {
            // object descriptor
            i++; // skip 'L'
            while (i < len && descriptor.charAt(i) != ';') {
                i++;
            }
            if (i >= len) {
                throw new IllegalArgumentException("Missing ';' in object descriptor in " + descriptor);
            }
            i++; // skip ';'
        } else {
            throw new IllegalArgumentException("Unknown descriptor character '" + c + "' at position " + i + " in " + descriptor);
        }
        try {
            outputStack.pop();
        } catch (Exception e) {
            throw new IllegalStateException("Failed to pop from outputStack while processing descriptor " + descriptor, e);
        }
    }
}

private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }

    // Helper lambda to pop one type from the stack
    Runnable popOne = () -> {
        // In actual implementation this would pop from the frame stack, e.g.:
        // frame.pop();
    };

    // If descriptor starts with '(' it is a method descriptor
    if (descriptor.charAt(0) == '(') {
        int end = descriptor.indexOf(')');
        if (end == -1) {
            // malformed descriptor, nothing to pop
            return;
        }
        String args = descriptor.substring(1, end);
        int i = 0;
        while (i < args.length()) {
            char c = args.charAt(i);
            if (c == 'L') {
                // Object type: read until ';'
                int semicolon = args.indexOf(';', i);
                if (semicolon == -1) {
                    // malformed descriptor
                    return;
                }
                i = semicolon + 1;
            } else if (c == '[') {
                // Array type: skip all '[' chars
                i++;
                continue;
            } else {
                // Primitive type: advance one char
                i++;
            }
            // Pop one type from the stack
            popOne.run();
        }
    } else {
        // Descriptor represents a single type
        int i = 0;
        char c = descriptor.charAt(i);
        if (c == 'L') {
            int semicolon = descriptor.indexOf(';', i);
            if (semicolon == -1) {
                return;
            }
            i = semicolon + 1;
        } else if (c == '[') {
            while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                i++;
            }
            if (i < descriptor.length() && descriptor.charAt(i) == 'L') {
                int semicolon = descriptor.indexOf(';', i);
                if (semicolon == -1) {
                    return;
                }
                i = semicolon + 1;
            } else {
                // Primitive array type
                i = i + 1;
            }
        } else {
            i = i + 1; // primitive type
        }
        // Pop the single type
        popOne.run();
    }
}

