public static String applyRelativePath(String path,String relativePath){
    if (path == null) return null;
    try {
        // Determine base directory (exclude file name if present)
        String base = path;
        int lastSlash = base.lastIndexOf('/');
        if (lastSlash != -1) {
            base = base.substring(0, lastSlash + 1); // keep trailing slash
        } else {
            base = "";
        }

        java.util.ArrayDeque<String> stack = new java.util.ArrayDeque<>();

        // Add base parts to stack
        if (!base.isEmpty()) {
            for (String part : base.split("/")) {
                if (part.isEmpty() || part.equals(".")) {
                    continue;
                } else if (part.equals("..")) {
                    stack.pollLast();
                } else {
                    stack.addLast(part);
                }
            }
        }

        // Add relative parts to stack
        if (relativePath != null && !relativePath.isEmpty()) {
            for (String part : relativePath.split("/")) {
                if (part.isEmpty() || part.equals(".")) {
                    continue;
                } else if (part.equals("..")) {
                    stack.pollLast();
                } else {
                    stack.addLast(part);
                }
            }
        }

        // Build the resulting path, preserving leading slash if the original path started with one
        java.lang.StringBuilder result = new java.lang.StringBuilder();
        if (path.startsWith("/")) {
            result.append("/");
        }

        java.util.Iterator<String> it = stack.iterator();
        while (it.hasNext()) {
            result.append(it.next());
            if (it.hasNext()) {
                result.append("/");
            }
        }

        return result.toString();
    } catch (Exception e) {
        return null;
    }
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null) {
        throw new IllegalArgumentException("path must not be null");
    }
    if (relativePath == null) {
        throw new IllegalArgumentException("relativePath must not be null");
    }

    // Normalize separators
    path = path.replace('\\', '/');
    relativePath = relativePath.replace('\\', '/');

    // Determine the base directory part of the path
    String baseDir;
    if (path.endsWith("/")) {
        baseDir = path;
    } else {
        int lastSlash = path.lastIndexOf('/');
        baseDir = (lastSlash >= 0) ? path.substring(0, lastSlash + 1) : "";
    }

    java.util.List<String> components = new java.util.ArrayList<>();

    // Add base directory components
    if (!baseDir.isEmpty()) {
        for (String comp : baseDir.split("/")) {
            if (!comp.isEmpty()) {
                components.add(comp);
            }
        }
    }

    // Process relative path components
    for (String comp : relativePath.split("/")) {
        if (comp.isEmpty() || comp.equals(".")) {
            continue;
        }
        if (comp.equals("..")) {
            if (!components.isEmpty()) {
                components.remove(components.size() - 1);
            }
        } else {
            components.add(comp);
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (path.startsWith("/")) {
        result.append("/");
    }
    for (int i = 0; i < components.size(); i++) {
        result.append(components.get(i));
        if (i < components.size() - 1) {
            result.append("/");
        }
    }
    if (result.length() == 0) {
        result.append("/");
    }
    return result.toString();
}

public static String applyRelativePath(String path,String relativePath){
    if (path == null || relativePath == null) {
        return null;
    }
    try {
        java.nio.file.Path base = java.nio.file.Paths.get(path);
        java.nio.file.Path result;
        if (relativePath.startsWith("/")) {
            result = java.nio.file.Paths.get(relativePath);
        } else {
            java.nio.file.Path parent = base.getParent();
            result = (parent != null) ? parent.resolve(relativePath) : java.nio.file.Paths.get(relativePath);
        }
        return result.toAbsolutePath().normalize().toString();
    } catch (Exception e) {
        return null;
    }
}

