    if (array == null || array.length == 0) {
        return (String[]) array;
    }
    int nullCount = 0;
    for (Object o : array) {
        if (o == null) {
            nullCount++;
        }
    }
    if (nullCount == 0) {
        if (array instanceof String[]) {
            return (String[]) array;
        } else {
            String[] copy = new String[array.length];
            for (int i = 0; i < array.length; i++) {
                copy[i] = (String) array[i];
            }
            return copy;
        }
    }
    String[] result = new String[array.length - nullCount];
    int idx = 0;
    for (Object o : array) {
        if (o != null) {
            result[idx++] = (String) o;
        }
    }
    return result;
}

