        throw new IOException("Failed to deserialize ThreadSnapshot objects", e);
    }
    return result;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IOException("File argument is null.");
    }
    if (!file.isFile()) {
        throw new IOException("The specified path does not point to a regular file.");
    }
    List<ThreadSnapshot> result = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            try {
                // Attempt to parse a snapshot from the line.
                ThreadSnapshot snapshot = ThreadSnapshot.parseSnapshot(line);
                if (snapshot == null) {
                    continue; // skip unparsable snapshots
                }
                if (timeRanges == null || timeRanges.isEmpty()) {
                    result.add(snapshot);
                } else {
                    long ts = snapshot.getTimestamp(); // assume a method returning millisecond timestamp
                    for (ProfileAnalyzeTimeRange range : timeRanges) {
                        if (range.contains(ts)) {
                            result.add(snapshot);
                            break;
                        }
                    }
                }
            } catch (Exception e) {
                // Skip malformed lines but keep the loop running.
                // In a real implementation, consider logging.
            }
        }
    } catch (IOException e) {
        throw e; // re‑throw underlying I/O failures
    } catch (Exception e) {
        // Wrap any unexpected runtime exception into an IOException
        throw new IOException("Unexpected error while parsing thread snapshots", e);
    }
    return result;
}
